const root=document.querySelector('#adminRoot'),dialog=document.querySelector('#editor');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(v);
const stamp=v=>v?new Date(v).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Ещё не публиковалось';
const state={page:'dishes',menu:null,dirty:false,preview:false,email:'',query:'',category:'',status:'',busy:false};
let setupKey=new URLSearchParams(location.hash.slice(1)).get('setup')||'';
if(location.hash)history.replaceState(null,'',location.pathname+location.search);
let noticeTimer;
function notify(message){const box=document.querySelector('#notice');box.textContent=message;box.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>box.classList.remove('show'),4200);}
async function request(action,body){const response=await fetch('/api/manage?action='+encodeURIComponent(action),{cache:'no-store',credentials:'same-origin',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json','X-Sof-Admin':'1'},body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Не удалось выполнить запрос.');error.status=response.status;throw error;}return data;}
function authScreen({setup=false,error='',configuration=false}={}){
  root.innerHTML=`<main class="login-shell"><section class="login-art"><a class="brand" href="/">СОФ<small>КАБИНЕТ РЕСТОРАНА</small></a><div><span class="eyebrow">ВАШЕ МЕНЮ. ВАШИ ПРАВИЛА.</span><h1>Всё вкусное —<br>под вашим<br>управлением.</h1><p>Добавляйте блюда, обновляйте цены и сообщайте гостям, что сегодня есть в наличии.</p></div><footer>Соф · Управление меню</footer></section><section class="login-box"><div class="login-inner"><a class="brand" href="/">СОФ<small>КАБИНЕТ РЕСТОРАНА</small></a><span class="eyebrow">${setup?'ПЕРВЫЙ ВХОД':'РАДЫ ВАС ВИДЕТЬ'}</span><h2>${configuration?'Кабинет готовится':setup?'Создайте вход владельца':'Войти в кабинет'}</h2><p>${configuration?'Панель подготовлена. Чтобы включить сохранение, подключите хранилище к проекту.':setup?'Укажите ваш email и придумайте пароль. Эта личная ссылка используется только один раз.':'Управляйте меню «Соф» с телефона или компьютера.'}</p>${configuration?`<div class="banner">${escape(error)}</div><button class="button" id="previewAdmin">Посмотреть панель</button><p class="login-hint">Предпросмотр не сохраняет изменения в меню.</p>`:`<form id="authForm" data-setup="${setup}"><label class="field">Email<input type="email" name="email" autocomplete="username" maxlength="254" required></label><label class="field">Пароль<input type="password" name="password" autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="12"':''} maxlength="128" required>${setup?'<small>Не менее 12 символов. Используйте уникальный пароль.</small>':''}</label>${setup?'<label class="field">Повторите пароль<input type="password" name="confirm" autocomplete="new-password" minlength="12" maxlength="128" required></label>':''}<p class="error-text" id="authError" role="alert">${escape(error)}</p><button class="button" type="submit">${setup?'Создать кабинет':'Войти'}</button></form><p class="login-hint">${setup?'После регистрации меню станет доступно для редактирования.':'Доступ только для владельца кафе.'}</p>`}<p class="login-hint"><a href="/">← Вернуться к меню</a></p></div></section></main>`;
}
async function start(){try{const session=await request('session');if(session.authenticated){state.email=session.email;await loadMenu();}else if(session.needsSetup){if(setupKey)authScreen({setup:true});else authScreen({configuration:true,error:'Владелец ещё не зарегистрирован. Для активации нужна личная ссылка настройки.'});}else authScreen();}catch(e){authScreen({configuration:true,error:e.message});}}
async function loadMenu(){state.menu=await request('menu');state.dirty=false;state.preview=false;render();}
function setDirty(){state.dirty=true;updateSavebar();}
function savebar(){return `<div class="savebar"><div><strong>${state.preview?'Предпросмотр панели':state.dirty?'Есть неопубликованные изменения':'Меню сохранено'}</strong><small>${state.preview?'В этом режиме изменения не сохраняются':state.dirty?'Гости увидят их после сохранения':stamp(state.menu.updatedAt)}</small></div><div class="save-actions">${state.dirty?'<button class="button secondary" id="discard">Отменить</button>':''}<button class="button orange" id="saveMenu" ${!state.dirty||state.busy||state.preview?'disabled':''}>${state.busy?'Сохраняем…':'Сохранить изменения'}</button></div></div>`;}
function updateSavebar(){const old=document.querySelector('.savebar');if(old)old.outerHTML=savebar();}
function render(){const menu=state.menu;if(!menu)return;root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="/">СОФ<small>УПРАВЛЕНИЕ МЕНЮ</small></a><nav aria-label="Разделы кабинета">${[['dishes','◫','Блюда'],['categories','≡','Категории'],['settings','⚙','Настройки'],['backups','↶','Копии']].map(([id,icon,label])=>`<button class="nav-link ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><a href="/" target="_blank" rel="noopener">Открыть меню ↗</a><button class="text-button" id="logout">${state.preview?'Вернуться ко входу':'Выйти из кабинета'}</button></div></aside><main class="main"><div class="topbar"><span>Кабинет ресторана</span><div class="account"><span class="avatar" aria-hidden="true">${escape((state.email||'С')[0].toUpperCase())}</span><span class="account-label">${escape(state.preview?'Предпросмотр':state.email)}</span><a class="preview-link" href="/" target="_blank" rel="noopener">Меню ↗</a></div></div>${state.preview?'<div class="banner">Предпросмотр. Можно изучить панель и заполнить поля. Изменения не попадут в меню, пока не подключены хранилище и вход владельца.</div>':''}${state.page==='dishes'?dishPage():state.page==='categories'?categoryPage():state.page==='settings'?settingsPage():backupsPage()}</main>${savebar()}</div>`;}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function dishPage(){return heading('МЕНЮ КАФЕ','Блюда','Вкус начинается с хорошего меню.','<button class="button" id="addDish">+ Добавить блюдо</button>')+`<div class="summary-strip"><span><strong>${state.menu.dishes.length}</strong>всего</span><span><strong>${state.menu.dishes.filter(d=>d.available&&d.published).length}</strong>в наличии</span><span><strong>${state.menu.dishes.filter(d=>!d.available&&d.published).length}</strong>в стоп-листе</span></div><div class="toolbar"><input class="search-input" id="dishSearch" type="search" placeholder="Поиск по названию блюда" aria-label="Поиск блюд" value="${escape(state.query)}"><select id="categoryFilter" aria-label="Категория"><option value="">Все категории</option>${state.menu.categories.map(c=>`<option value="${c.id}" ${c.id===state.category?'selected':''}>${escape(c.name)}</option>`).join('')}</select><select id="statusFilter" aria-label="Статус"><option value="">Все статусы</option><option value="available" ${state.status==='available'?'selected':''}>В наличии</option><option value="stop" ${state.status==='stop'?'selected':''}>Стоп-лист</option><option value="hidden" ${state.status==='hidden'?'selected':''}>Скрытые</option></select></div><div class="table-wrap"><table><thead><tr><th>Блюдо</th><th class="category-td">Категория</th><th>Цена</th><th>Статус</th><th><span class="optional-col">Действия</span></th></tr></thead><tbody id="dishRows">${dishRows()}</tbody></table></div>`;}
function dishRows(){const dishes=state.menu.dishes.filter(d=>d.name.toLowerCase().includes(state.query.toLowerCase())&&(!state.category||d.categoryId===state.category)&&(!state.status||(state.status==='hidden'?!d.published:state.status==='stop'?d.published&&!d.available:d.published&&d.available)));if(!dishes.length)return '<tr><td colspan="5" class="empty">Блюд пока нет.<br>Добавьте новое блюдо или измените фильтры.</td></tr>';return dishes.map(d=>`<tr><td class="dish-td"><div class="dish-cell">${d.imageUrl?`<img class="dish-thumb" src="${escape(d.imageUrl)}" alt="" loading="lazy">`:'<span class="dish-thumb no-photo" aria-hidden="true">♧</span>'}<span><strong class="dish-name">${escape(d.name)}</strong><small class="dish-weight">${escape(d.weight||'Вес не указан')}</small></span></div></td><td class="category-td">${escape(state.menu.categories.find(c=>c.id===d.categoryId)?.name)}</td><td class="price price-td">${currency(d.price)}</td><td class="status-td"><span class="badge ${!d.published?'hidden':!d.available?'off':''}">${!d.published?'Скрыто':!d.available?'Стоп-лист':'В наличии'}</span></td><td class="actions-td"><div class="row-actions"><button class="icon-button" data-edit="${d.id}" aria-label="Изменить: ${escape(d.name)}">Изменить</button><button class="icon-button" data-toggle="${d.id}" aria-label="${d.available?'В стоп-лист':'Вернуть в наличие'}: ${escape(d.name)}">${d.available?'Пауза':'Вернуть'}</button></div></td></tr>`).join('');}
function categoryPage(){return heading('СТРУКТУРА МЕНЮ','Категории','Объединяйте блюда и меняйте порядок разделов.','<button class="button" id="addCategory">+ Категория</button>')+`<div class="category-list">${state.menu.categories.map((c,index)=>`<div class="category-row"><strong>${escape(c.name)}</strong><small>${state.menu.dishes.filter(d=>d.categoryId===c.id).length} блюд</small><button class="icon-button" data-move-category="${c.id}" data-direction="-1" ${!index?'disabled':''} aria-label="Поднять: ${escape(c.name)}">↑</button><button class="icon-button" data-move-category="${c.id}" data-direction="1" ${index===state.menu.categories.length-1?'disabled':''} aria-label="Опустить: ${escape(c.name)}">↓</button><button class="icon-button" data-category-edit="${c.id}">Изменить</button></div>`).join('')}</div>`;}
function settingsPage(){const fields=[['name','Название кафе','Соф'],['tagline','Подпись на главной','Закажите в «Соф».'],['phone','Телефон','+7 …'],['hours','Режим работы','Ежедневно 10:00–00:00'],['address','Адрес','Улица, дом'],['deliveryNote','Условия доставки','Зона, стоимость и время доставки']];return heading('ИНФОРМАЦИЯ ДЛЯ ГОСТЕЙ','Настройки кафе','Сохраняйте актуальные контакты и условия заказа.')+`<section class="panel"><h2>Основная информация</h2><div class="form-grid">${fields.map(([key,label,placeholder])=>`<label class="field ${['address','deliveryNote'].includes(key)?'full':''}">${label}${key==='deliveryNote'?`<textarea data-setting="${key}" maxlength="600" placeholder="${placeholder}">${escape(state.menu.settings[key])}</textarea>`:`<input data-setting="${key}" value="${escape(state.menu.settings[key])}" maxlength="180" ${key==='name'?'required':''} placeholder="${placeholder}">`}</label>`).join('')}</div></section><section class="panel"><h2>Приём заказов</h2><p>Управление меню работает отдельно. Приём реальных заказов и онлайн-оплату подключим следующим этапом.</p></section>`;}
function backupsPage(){return heading('СОХРАННОСТЬ ДАННЫХ','Резервные копии','Последние пять публикаций сохраняются автоматически.')+`<section class="panel"><h2>Скачать текущие данные</h2><p>JSON-файл содержит блюда, категории и настройки. Паролей и данных входа в нём нет.</p><button class="button secondary" id="exportMenu">Скачать меню</button></section><section class="panel"><h2>История публикаций</h2>${(state.menu.history||[]).slice().reverse().map(h=>`<div class="backup-row"><span>Версия ${h.revision}<small>${stamp(h.updatedAt)} · ${h.dishes.length} блюд</small></span><button class="button secondary" data-restore="${h.revision}" ${state.preview?'disabled':''}>Восстановить</button></div>`).join('')||'<p>После первой публикации здесь появится предыдущая версия.</p>'}</section>`;}
function dialogHead(title){return `<div class="dialog-head"><h2>${title}</h2><button type="button" class="icon-button" id="closeEditor" aria-label="Закрыть">✕</button></div>`;}
function editDish(id){const old=state.menu.dishes.find(d=>d.id===id);const d=old||{id:crypto.randomUUID(),name:'',price:'',weight:'',categoryId:state.menu.categories[0]?.id,desc:'',imageUrl:'',available:true,published:true};dialog.innerHTML=dialogHead(old?'Изменить блюдо':'Новое блюдо')+`<form id="dishForm" data-id="${d.id}"><div class="photo-upload">${d.imageUrl?`<img id="photoPreview" src="${escape(d.imageUrl)}" alt="Фото блюда">`:'<img id="photoPreview" alt="Фото не выбрано" hidden>'}<div><label for="photoInput">Фотография блюда</label><input id="photoInput" name="photo" type="file" accept="image/png,image/jpeg,image/webp" ${state.preview?'disabled':''}><p>${state.preview?'Загрузка доступна после подключения кабинета.':'PNG, JPEG или WebP · до 2 МБ. Для карточек лучше фото без фона.'}</p><button class="text-button" type="button" id="removePhoto">Убрать фото</button></div></div><div class="form-grid"><label class="field full">Название<input name="name" maxlength="120" value="${escape(d.name)}" required></label><label class="field">Цена, ₽<input type="number" name="price" min="0" max="100000" step="0.01" inputmode="decimal" value="${d.price}" required></label><label class="field">Вес / количество<input name="weight" maxlength="40" placeholder="450 г или 5 шт." value="${escape(d.weight)}"></label><label class="field full">Категория<select name="categoryId">${state.menu.categories.map(c=>`<option value="${c.id}" ${c.id===d.categoryId?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><label class="field full">Описание / состав<textarea name="desc" maxlength="1500" placeholder="Укажите состав и особенности блюда">${escape(d.desc)}</textarea></label></div><div class="checks"><label class="check"><input type="checkbox" name="published" ${d.published?'checked':''}>Показывать в меню</label><label class="check"><input type="checkbox" name="available" ${d.available?'checked':''}>Есть в наличии (снимите, чтобы добавить в стоп-лист)</label></div><input type="hidden" name="imageUrl" value="${escape(d.imageUrl)}"><p class="error-text" id="formError" role="alert"></p><div class="dialog-actions">${old?'<button class="button danger" type="button" id="deleteDish">Удалить</button>':''}<button class="button secondary" type="button" id="cancelEditor">Отмена</button><button class="button" type="submit">Применить</button></div></form>`;dialog.showModal();dialog.querySelector('[name=name]').focus();}
function editCategory(id){const c=state.menu.categories.find(c=>c.id===id)||{id:crypto.randomUUID(),name:''};dialog.innerHTML=dialogHead(id?'Изменить категорию':'Новая категория')+`<form id="categoryForm" data-id="${c.id}"><label class="field">Название<input name="name" maxlength="60" value="${escape(c.name)}" required></label><p class="error-text" id="formError" role="alert"></p><div class="dialog-actions">${id?'<button class="button danger" type="button" id="deleteCategory">Удалить</button>':''}<button class="button secondary" type="button" id="cancelEditor">Отмена</button><button class="button" type="submit">Применить</button></div></form>`;dialog.showModal();dialog.querySelector('input').focus();}
function exportMenu(){const {history,...menu}=state.menu;const blob=new Blob([JSON.stringify(menu,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sof-menu-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function saveMenu(){if(!state.dirty||state.preview||state.busy)return;state.busy=true;updateSavebar();try{const result=await request('save',state.menu);await loadMenu();notify('Меню опубликовано. Гости увидят новые данные при обновлении.');}catch(e){notify(e.message);}finally{state.busy=false;updateSavebar();}}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;try{
  if(b.dataset.page){state.page=b.dataset.page;render();}
  else if(b.id==='previewAdmin'){const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)throw new Error('Предпросмотр временно недоступен.');state.menu=await response.json();state.preview=true;state.email='';render();}
  else if(b.id==='addDish')editDish();else if(b.dataset.edit)editDish(b.dataset.edit);
  else if(b.dataset.toggle){const d=state.menu.dishes.find(d=>d.id===b.dataset.toggle);d.available=!d.available;setDirty();render();}
  else if(b.id==='addCategory')editCategory();else if(b.dataset.categoryEdit)editCategory(b.dataset.categoryEdit);
  else if(b.dataset.moveCategory){const list=state.menu.categories,index=list.findIndex(c=>c.id===b.dataset.moveCategory);[list[index],list[index+Number(b.dataset.direction)]]=[list[index+Number(b.dataset.direction)],list[index]];setDirty();render();}
  else if(['closeEditor','cancelEditor'].includes(b.id))dialog.close();
  else if(b.id==='removePhoto'){dialog.querySelector('[name=imageUrl]').value='';dialog.querySelector('#photoInput').value='';dialog.querySelector('#photoPreview').hidden=true;}
  else if(b.id==='deleteDish'){if(confirm('Удалить это блюдо? Изменение попадёт в меню после сохранения.')){state.menu.dishes=state.menu.dishes.filter(d=>d.id!==dialog.querySelector('form').dataset.id);dialog.close();setDirty();render();}}
  else if(b.id==='deleteCategory'){const id=dialog.querySelector('form').dataset.id;if(state.menu.dishes.some(d=>d.categoryId===id))throw new Error('Сначала перенесите блюда этой категории в другую.');if(state.menu.categories.length===1)throw new Error('В меню должна остаться хотя бы одна категория.');if(confirm('Удалить категорию?')){state.menu.categories=state.menu.categories.filter(c=>c.id!==id);dialog.close();setDirty();render();}}
  else if(b.id==='saveMenu')await saveMenu();
  else if(b.id==='discard'&&confirm('Отменить все неопубликованные изменения?')){if(state.preview){await start();}else await loadMenu();}
  else if(b.id==='logout'){if(state.dirty&&!confirm('Есть неопубликованные изменения. Выйти без сохранения?'))return;if(!state.preview)await request('logout',{});state.dirty=false;state.preview=false;state.menu=null;await start();}
  else if(b.id==='exportMenu')exportMenu();
  else if(b.dataset.restore!==undefined){if(state.dirty)throw new Error('Сначала сохраните или отмените текущие изменения.');if(confirm('Восстановить выбранную версию меню? Текущее меню сохранится в истории.')){await request('restore',{revision:state.menu.revision,restoreRevision:Number(b.dataset.restore)});await loadMenu();notify('Версия восстановлена.');}}
}catch(e){if(dialog.open){const p=dialog.querySelector('#formError');if(p)p.textContent=e.message;else notify(e.message);}else notify(e.message);}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='dishSearch'){state.query=el.value;document.querySelector('#dishRows').innerHTML=dishRows();}else if(el.dataset.setting){state.menu.settings[el.dataset.setting]=el.value;setDirty();}});
document.addEventListener('change',event=>{if(event.target.id==='categoryFilter'){state.category=event.target.value;document.querySelector('#dishRows').innerHTML=dishRows();}if(event.target.id==='statusFilter'){state.status=event.target.value;document.querySelector('#dishRows').innerHTML=dishRows();}if(event.target.id==='photoInput'){const file=event.target.files[0];if(file){if(file.size>2097152||!['image/png','image/jpeg','image/webp'].includes(file.type)){event.target.value='';notify('Выберите JPEG, PNG или WebP до 2 МБ.');return;}const img=document.querySelector('#photoPreview');if(img.dataset.objectUrl)URL.revokeObjectURL(img.dataset.objectUrl);img.src=URL.createObjectURL(file);img.dataset.objectUrl=img.src;img.hidden=false;}}});
dialog.addEventListener('close',()=>{const img=dialog.querySelector('#photoPreview');if(img?.dataset.objectUrl)URL.revokeObjectURL(img.dataset.objectUrl);});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]'),error=form.querySelector('[role=alert]');button.disabled=true;if(error)error.textContent='';try{
  if(form.id==='authForm'){const setup=form.dataset.setup==='true';if(setup&&form.elements.password.value!==form.elements.confirm.value)throw new Error('Пароли не совпадают.');await request(setup?'setup':'login',{email:form.elements.email.value,password:form.elements.password.value,...(setup?{setupKey}:{})});setupKey='';await start();}
  else if(form.id==='categoryForm'){const name=form.elements.name.value.trim();if(!name)throw new Error('Введите название категории.');if(state.menu.categories.some(c=>c.name.toLowerCase()===name.toLowerCase()&&c.id!==form.dataset.id))throw new Error('Такая категория уже есть.');const c=state.menu.categories.find(c=>c.id===form.dataset.id);if(c)c.name=name;else state.menu.categories.push({id:form.dataset.id,name});dialog.close();setDirty();render();}
  else if(form.id==='dishForm'){
    let imageUrl=form.elements.imageUrl.value;const file=form.elements.photo.files[0];
    if(file){if(state.preview)throw new Error('Загрузка фото доступна после подключения.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Не удалось прочитать фото.'));reader.readAsDataURL(file);});const response=await fetch('/api/media',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Sof-Admin':'1'},body:JSON.stringify({data})});const result=await response.json();if(!response.ok)throw new Error(result.error);imageUrl=result.imageUrl;}
    const d={id:form.dataset.id,name:form.elements.name.value.trim(),price:Number(form.elements.price.value),weight:form.elements.weight.value.trim(),categoryId:form.elements.categoryId.value,desc:form.elements.desc.value.trim(),imageUrl,available:form.elements.available.checked,published:form.elements.published.checked};
    if(!d.name||!Number.isFinite(d.price)||d.price<0)throw new Error('Укажите название и корректную цену.');const index=state.menu.dishes.findIndex(x=>x.id===d.id);if(index<0)state.menu.dishes.push(d);else state.menu.dishes[index]=d;dialog.close();setDirty();render();notify('Блюдо изменено в черновике. Сохраните меню, чтобы опубликовать.');
  }
}catch(e){if(error)error.textContent=e.message;else notify(e.message);}finally{if(button.isConnected)button.disabled=false;}});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
start();
